<!doctype html><html lang="en" class="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= h($_SESSION['csrf_token']) ?>"><title>Credential Vault · ThriveWell OS</title><link rel="stylesheet" href="/build/app.css"><script defer src="/build/app.js"></script></head>
<body><main class="credential-page"><section class="credential-hero card"><span class="eyebrow">Private credential vault</span><h1>Professional trust, handled gently.</h1><p>Upload credential metadata for private storage review. Documents stay private, signed access is time-limited, and every review action is audited.</p><div class="credential-summary"><div><strong><?= h((string) $vault['summary']['verified']) ?></strong><span>Verified</span></div><div><strong><?= h((string) $vault['summary']['pending_review']) ?></strong><span>Pending</span></div><div><strong><?= h((string) $vault['summary']['revision_requested']) ?></strong><span>Needs revision</span></div></div><a class="link-inline" href="/dashboard">← Back to dashboard</a></section>
<section class="card credential-submit"><div class="card-head"><h2>Submit credential metadata</h2><span>Private disk readiness</span></div><div class="state-strip" aria-live="polite"><div class="success-state" hidden>Saved.</div><div class="error-state" hidden>Check details.</div></div><form data-async-form action="/credentials/submit" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><label>Document type<select name="document_type"><?php foreach ($vault['requirements'] as $requirement): ?><option value="<?= h($requirement['type']) ?>"><?= h($requirement['label'].' · '.$requirement['required_for']) ?></option><?php endforeach; ?></select></label><label>Display title<input name="title" placeholder="e.g. Professional counselling license" required></label><label>Private storage path<input name="storage_path" value="private/credentials/new-credential.pdf" required></label><button type="submit">Submit for review</button></form></section>
<section class="card credential-list"><div class="card-head"><h2>Your credential documents</h2><span>Signed URL ready</span></div><?php foreach ($vault['documents'] as $document): ?><article class="credential-card <?= h($document['status']) ?>"><div><strong><?= h($document['title']) ?></strong><span><?= h($document['document_type']) ?> · <?= h($document['storage_disk']) ?> · <?= h($document['storage_path']) ?></span><small>SHA-256 <?= h(substr($document['file_hash'], 0, 16)) ?> · Expires <?= h($document['expires_at']) ?></small><?php if ($document['revision_reason']): ?><p><?= h($document['revision_reason']) ?></p><?php endif; ?></div><?= status_pill($document['status']) ?><form data-async-form action="/credentials/signed-download" method="post"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="credential_document_id" value="<?= h((string) $document['id']) ?>"><button type="submit">Create signed access</button></form></article><?php endforeach; ?></section>
<section class="card credential-list"><div class="card-head"><h2>Verification badges</h2><span>Trust signals</span></div><?php foreach ($vault['badges'] as $badge): ?><article class="badge-row"><strong><?= h($badge['badge']) ?></strong><span><?= h($badge['level']) ?></span><?= status_pill($badge['status']) ?></article><?php endforeach; ?></section></main></body></html>
